import type { Action } from 'svelte/action';

// A click event generated by the keyboard has a click count (detail) of zero
const KEYBOARD_CLICK_DETAIL = 0;

// Native controls that Safari and iPadOS do not focus when pressed. An element with a tabindex
// takes focus on a press in every browser, so its focusin already marks the container.
const PRESSABLE_SELECTOR = 'button, a[href], area[href], input, select, textarea, summary';

type FocusTarget = HTMLElement | SVGElement;

/**
 * Elements to try, in order, when the container goes away while it holds focus. An empty
 * list leaves focus where it is.
 */
export type FocusFallback = () => Array<HTMLElement | null | undefined>;

/** Focus return for a dismissible container, created once per component instance. */
export interface FocusReturn {
  /**
   * Svelte action for the container's root element. It remembers where focus
   * came from before it entered the container.
   */
  track: Action<HTMLElement>;
  /**
   * Moves focus back to where it came from. Call it from the dismiss handler
   * with the click event, before the container is hidden: dismissing removes the
   * focused button, and without this the browser drops focus to the document body.
   */
  restore: (event: MouseEvent) => void;
}

/**
 * Creates the focus return for one dismissible container (an alert or a banner).
 * Destructure the result and put `use:track` on the container's root element.
 *
 * With `fallback`, the container also keeps focus near the user's place when it goes
 * away for any other reason (a Retry that succeeded, a mouse dismiss, a refresh that
 * cleared it): removing the focused element drops focus to the document body, so focus
 * moves to the first fallback element that can take it instead. The container counts as
 * holding focus from a focusin, or from a pointerdown on a native control inside it (Safari
 * and iPadOS do not focus a clicked button, so the user's place is where they pressed),
 * until focus moves to another element. A press on plain content inside the container,
 * including content inside a tabindex element, does not count by itself: it leaves focus
 * on the page body, or focuses the tabindex element, which its own focusin then records.
 * Focus that was inside and then left for nothing (a click on plain page content) still
 * counts, so removal then runs the fallback. A later press on the page outside the
 * container, while focus is not inside it, clears the mark, whether it came from a press
 * or from focus that has since left. A fallback that returns an empty list leaves focus
 * where it is.
 */
export function createFocusReturn(fallback?: FocusFallback): FocusReturn {
  // Each tracked element keeps its own state, so an outgoing element whose destroy runs after
  // a newer one mounted (a branch with an exit transition) cannot clear or inherit the newer
  // element's hold, return target or listeners. restore acts on the element mounted last.
  let current: TrackedContainer | undefined;

  const track: Action<HTMLElement> = node => {
    const tracked = trackContainer(node, fallback);
    current = tracked;
    return {
      destroy() {
        tracked.destroy();
        if (current === tracked) current = undefined;
      },
    };
  };

  function restore(event: MouseEvent) {
    current?.restore(event);
  }

  return { track, restore };
}

interface TrackedContainer {
  restore: (event: MouseEvent) => void;
  destroy: () => void;
}

/** Listens on one container element; see createFocusReturn for what counts as holding focus. */
function trackContainer(root: HTMLElement, fallback: FocusFallback | undefined): TrackedContainer {
  let returnFocusTo: FocusTarget | null = null;
  let holdsFocus = false;

  function handleHold(event: PointerEvent) {
    const control =
      event.target instanceof Element ? event.target.closest(PRESSABLE_SELECTOR) : null;
    if (control && root.contains(control)) holdsFocus = true;
  }

  function handleFocusIn(event: FocusEvent) {
    holdsFocus = true;
    const from = event.relatedTarget;
    // Only focus arriving from an element outside the container replaces the target.
    // Moving between controls inside the container keeps it, and so does focus with no
    // related element (the window or tab regaining focus while a control in the
    // container is focused, or a click on plain page content). That can leave an older
    // target in place after a later entry from the page body, which is harmless:
    // restore only uses it while it is still connected and outside the container.
    if (!(from instanceof HTMLElement || from instanceof SVGElement)) return;
    if (root.contains(from)) return;
    returnFocusTo = from;
  }

  function handleFocusOut(event: FocusEvent) {
    if (event.relatedTarget instanceof Node && !root.contains(event.relatedTarget)) {
      holdsFocus = false;
    }
    // Focus left for the page body (a click on non-focusable content): forget the
    // target, so a later Tab back in and keyboard dismiss does not jump to a field
    // that may be far away. A window or tab blur also fires focusout with no related
    // element, but the document has lost focus by then, so the target is kept for
    // the refocus. Moves within the container, or to another element (re-entry sets
    // the target again), leave it alone.
    if (event.relatedTarget === null && document.hasFocus()) {
      returnFocusTo = null;
    }
  }

  // A press on the page outside the container while focus is not inside it: a control pressed
  // earlier that the browser did not focus (Safari) is no longer where the user is. Capture, so
  // a handler that stops propagation cannot hide the press.
  function handleOutsidePress(event: PointerEvent) {
    if (!(event.target instanceof Node) || root.contains(event.target)) return;
    if (!root.contains(document.activeElement)) holdsFocus = false;
  }

  document.addEventListener('pointerdown', handleOutsidePress, true);
  root.addEventListener('focusin', handleFocusIn);
  root.addEventListener('focusout', handleFocusOut);
  root.addEventListener('pointerdown', handleHold);

  return {
    restore(event: MouseEvent) {
      // Only for keyboard activation (Enter or Space on the button reports a click
      // with no click count). A mouse click leaves focus alone, so it does not jump
      // back to a far-away field and scroll the page. Also only when focus is
      // inside the container; otherwise leave focus where it is.
      if (
        event.detail === KEYBOARD_CLICK_DETAIL &&
        root.contains(document.activeElement) &&
        returnFocusTo?.isConnected &&
        !root.contains(returnFocusTo)
      ) {
        returnFocusTo.focus();
      }
    },
    destroy() {
      document.removeEventListener('pointerdown', handleOutsidePress, true);
      root.removeEventListener('focusin', handleFocusIn);
      root.removeEventListener('focusout', handleFocusOut);
      root.removeEventListener('pointerdown', handleHold);
      returnFocusTo = null;
      if (fallback && holdsFocus) {
        holdsFocus = false;
        // Svelte may run this before the node leaves the document. The fallback leaves
        // focus alone when it is already on an element (a newer container took it).
        queueMicrotask(() => focusFallback(fallback));
      }
    },
  };
}

function focusFallback(fallback: FocusFallback): void {
  if (document.activeElement && document.activeElement !== document.body) return;
  for (const el of fallback()) {
    if (!el?.isConnected) continue;
    // The alert may go away long after the user stopped looking at it, so do not scroll
    el.focus({ preventScroll: true });
    if (document.activeElement === el) return;
  }
}
